export const getGetCaseGraphUrl = (caseId: string,
    params?: GetCaseGraphParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/argus/cases/${caseId}/graph?${stringifiedParams}` : `/api/argus/cases/${caseId}/graph`
}

